528	function generateStatusline() {
529	  const d = getStatuslineData();
530	  const git = getGitInfo();
531	  const modelName = getModelFromStdin() || (d.user && d.user.modelName) || 'Claude Code';
532	  const ctxInfo = getContextFromStdin();
533	  const costInfo = getCostFromStdin();
534	  const pkgVersion = getPkgVersion();
535	
536	  const progress = d.v3Progress || {};
537	  const security = d.security || {};
538	  const swarm = d.swarm || {};
539	  const system = d.system || {};
540	  const adrs = d.adrs || {};
541	  const hooks = d.hooks || {};
542	  const agentdb = d.agentdb || {};
543	  const tests = d.tests || {};
544	
545	  const domainsCompleted = progress.domainsCompleted || 0;
546	  const totalDomains = progress.totalDomains || 5;
547	  const dddProgress = progress.dddProgress || 0;
548	  const patternsLearned = progress.patternsLearned || 0;
549	  const activeAgents = swarm.activeAgents || 0;
550	  const maxAgents = swarm.maxAgents || CONFIG.maxAgents;
551	  const coordinationActive = swarm.coordinationActive || false;
552	  const intelligencePct = system.intelligencePct || 0;
553	  const memoryMB = system.memoryMB || 0;
554	  const subAgents = system.subAgents || 0;
555	  const cvesFixed = security.cvesFixed || 0;
556	  const totalCves = security.totalCves || 0;
557	  const secStatus = security.status || 'NONE';
558	  const adrCount = adrs.count || 0;
559	  const adrImpl = adrs.implemented || 0;
560	  const hooksEnabled = hooks.enabled || 0;
561	  const hooksTotal = hooks.total || 0;
562	  const vectorCount = agentdb.vectorCount || 0;
563	  const hasHnsw = agentdb.hasHnsw || false;
564	  const dbSizeKB = agentdb.dbSizeKB || 0;
565	  const testFiles = tests.testFiles || 0;
566	  const testCases = tests.testCases || testFiles * 4;
567	
568	  const lines = [];
569	
570	  // Header
571	  let header = c.bold + c.brightPurple + '▊ Luna V' + pkgVersion + ' ' + c.reset;
572	  header += (coordinationActive ? c.brightCyan : c.dim) + '● ' + c.brightCyan + git.name + c.reset;
573	  if (git.gitBranch) {
574	    header += '  ' + c.dim + '│' + c.reset + '  ' + c.brightBlue + '⏇ ' + git.gitBranch + c.reset;
575	    const changes = git.modified + git.staged + git.untracked;
576	    if (changes > 0) {
577	      let ind = '';
578	      if (git.staged > 0) ind += c.brightGreen + '+' + git.staged + c.reset;
579	      if (git.modified > 0) ind += c.brightYellow + '~' + git.modified + c.reset;
580	      if (git.untracked > 0) ind += c.dim + '?' + git.untracked + c.reset;
581	      header += ' ' + ind;
582	    }
583	    if (git.ahead > 0) header += ' ' + c.brightGreen + '↑' + git.ahead + c.reset;
584	    if (git.behind > 0) header += ' ' + c.brightRed + '↓' + git.behind + c.reset;
585	  }
586	  header += '  ' + c.dim + '│' + c.reset + '  ' + c.purple + modelName + c.reset;
587	  const duration = costInfo ? costInfo.duration : '';
588	  if (duration) header += '  ' + c.dim + '│' + c.reset + '  ' + c.cyan + '⏱ ' + duration + c.reset;
589	  if (ctxInfo && ctxInfo.usedPct > 0) {
590	    const ctxColor = ctxInfo.usedPct >= 90 ? c.brightRed : ctxInfo.usedPct >= 70 ? c.brightYellow : c.brightGreen;
591	    header += '  ' + c.dim + '│' + c.reset + '  ' + ctxColor + '● ' + ctxInfo.usedPct + '% ctx' + c.reset;
592	  }
593	  if (!CONFIG.hideCost && costInfo && costInfo.costUsd > 0) {
594	    header += '  ' + c.dim + '│' + c.reset + '  ' + c.brightYellow + CONFIG.costSymbol + costInfo.costUsd.toFixed(2) + c.reset;
595	  }
596	  lines.push(header);
597	
598	  // Separator
599	  lines.push(c.dim + '─'.repeat(53) + c.reset);
600	
601	  // Line 1: DDD Domains
602	  const domainsColor = domainsCompleted >= 3 ? c.brightGreen : domainsCompleted > 0 ? c.yellow : c.red;
603	  let perfIndicator;
604	  if (hasHnsw && vectorCount > 0) {
605	    const speedup = vectorCount > 10000 ? '12500x' : vectorCount > 1000 ? '150x' : '10x';
606	    perfIndicator = c.brightGreen + '⚡ HNSW ' + speedup + c.reset;
607	  } else if (patternsLearned > 0) {
608	    const pk = patternsLearned >= 1000 ? (patternsLearned / 1000).toFixed(1) + 'k' : String(patternsLearned);
609	    perfIndicator = c.brightYellow + '📚 ' + pk + ' patterns' + c.reset;
610	  } else {
611	    perfIndicator = c.dim + '⚡ target: 150x-12500x' + c.reset;
612	  }
613	  lines.push(
614	    c.brightCyan + '🏗️  DDD Domains' + c.reset + '    ' + progressBar(domainsCompleted, totalDomains) + '  ' +
615	    domainsColor + domainsCompleted + c.reset + '/' + c.brightWhite + totalDomains + c.reset + '    ' + perfIndicator
616	  );
617	
618	  // Line 2: Swarm + Hooks + CVE + Memory + Intelligence
619	  const swarmInd = coordinationActive ? c.brightGreen + '◉' + c.reset : c.dim + '○' + c.reset;
620	  const agentsColor = activeAgents > 0 ? c.brightGreen : c.red;
621	  const secIcon = secStatus === 'CLEAN' ? '🟢' : (secStatus === 'IN_PROGRESS' || secStatus === 'STALE') ? '🟡' : (secStatus === 'NONE' ? '⚪' : '🔴');
622	  const secColor = secStatus === 'CLEAN' ? c.brightGreen : (secStatus === 'IN_PROGRESS' || secStatus === 'STALE') ? c.brightYellow : (secStatus === 'NONE' ? c.dim : c.brightRed);
623	  const hooksColor = hooksEnabled > 0 ? c.brightGreen : c.dim;
624	  const intellColor = intelligencePct >= 80 ? c.brightGreen : intelligencePct >= 40 ? c.brightYellow : c.dim;
625	
626	  lines.push(
627	    c.brightYellow + '🤖 Swarm' + c.reset + '  ' + swarmInd + ' [' + agentsColor + String(activeAgents).padStart(2) + c.reset + '/' + c.brightWhite + maxAgents + c.reset + ']  ' +
628	    c.brightPurple + '👥 ' + subAgents + c.reset + '    ' +
629	    c.brightBlue + '🪝 ' + hooksColor + hooksEnabled + c.reset + '/' + c.brightWhite + hooksTotal + c.reset + '    ' +
630	    secIcon + ' ' + secColor + 'CVE ' + cvesFixed + c.reset + '/' + c.brightWhite + totalCves + c.reset + '    ' +
631	    c.brightCyan + '💾 ' + memoryMB + 'MB' + c.reset + '    ' +
632	    intellColor + '🧠 ' + String(intelligencePct).padStart(3) + '%' + c.reset
633	  );
634	
635	  // Line 3: Architecture
636	  const dddColor = dddProgress >= 50 ? c.brightGreen : dddProgress > 0 ? c.yellow : c.red;
637	  const adrColor = adrCount > 0 ? (adrImpl === adrCount ? c.brightGreen : c.yellow) : c.dim;
638	  const adrDisplay = adrColor + '●' + adrImpl + '/' + adrCount + c.reset;
639	
640	  lines.push(
641	    c.brightPurple + '🔧 Architecture' + c.reset + '    ' +
642	    c.cyan + 'ADRs' + c.reset + ' ' + adrDisplay + '  ' + c.dim + '│' + c.reset + '  ' +
643	    c.cyan + 'DDD' + c.reset + ' ' + dddColor + '●' + String(dddProgress).padStart(3) + '%' + c.reset + '  ' + c.dim + '│' + c.reset + '  ' +
644	    c.cyan + 'Security' + c.reset + ' ' + secColor + '●' + secStatus + c.reset
645	  );
646	
647	  // Line 4: AgentDB, Tests, Integration
648	  const hnswInd = hasHnsw ? c.brightGreen + '⚡' + c.reset : '';
649	  const sizeDisp = dbSizeKB >= 1024 ? (dbSizeKB / 1024).toFixed(1) + 'MB' : dbSizeKB + 'KB';
650	  const vectorColor = vectorCount > 0 ? c.brightGreen : c.dim;
651	  const testColor = testFiles > 0 ? c.brightGreen : c.dim;
652	
653	  // MCP / DB integration from data
654	  const integration = d.integration || {};
655	  const mcpServers = (integration.mcpServers) || {};
656	  let integStr = '';
657	  if (mcpServers.total > 0) {
658	    const mcpCol = mcpServers.enabled === mcpServers.total ? c.brightGreen : mcpServers.enabled > 0 ? c.brightYellow : c.red;
659	    integStr += c.cyan + 'MCP' + c.reset + ' ' + mcpCol + '●' + mcpServers.enabled + '/' + mcpServers.total + c.reset;
660	  }
661	  if (integration.hasDatabase) integStr += (integStr ? '  ' : '') + c.brightGreen + '◆' + c.reset + 'DB';
662	  if (!integStr) integStr = c.dim + '● none' + c.reset;
663	
664	  lines.push(
665	    c.brightCyan + '📊 AgentDB' + c.reset + '    ' +
666	    c.cyan + 'Vectors' + c.reset + ' ' + vectorColor + '●' + vectorCount + hnswInd + c.reset + '  ' + c.dim + '│' + c.reset + '  ' +
667	    c.cyan + 'Size' + c.reset + ' ' + c.brightWhite + sizeDisp + c.reset + '  ' + c.dim + '│' + c.reset + '  ' +
668	    c.cyan + 'Tests' + c.reset + ' ' + testColor + '●' + testFiles + c.reset + ' ' + c.dim + '(~' + testCases + ' cases)' + c.reset + '  ' + c.dim + '│' + c.reset + '  ' +
669	    integStr
670	  );
671	
672	  return lines.join('\n');
673	}
