<div class="shell">
  <aside class="rail">
    <canvas id="lunapix" aria-label="LunaCore"></canvas>
    <span class="tag">solo · lean</span>
    <span class="ver">v1</span>
  </aside>

  <main class="main">
    <div class="hdr"><h1>LunaCore // dash</h1><span class="cur"></span></div>
    <p class="sub">quick reference · read the statusline, then act</p>

    <div class="block-label">context budget — read the <span style="color:var(--cyan)">%ctx</span> led</div>
    <div class="ctx">
      <div class="row g"><span class="led"></span><span class="pct">&lt; 60%</span><span class="say">send it <b>— pełna swoboda</b></span></div>
      <div class="row y"><span class="led"></span><span class="pct">60–85%</span><span class="say">compact maybe?</span></div>
      <div class="row r"><span class="led"></span><span class="pct">&gt; 85%</span><span class="say">compact this shit</span></div>
    </div>

    <div class="block-label">commands — type it</div>
    <div class="grid">
      <div class="card" style="--c:var(--cyan)"><span class="cmd">/ecc:plan "…"</span><span class="txt">plan first, waits for CONFIRM</span></div>
      <div class="card" style="--c:var(--cyan)"><span class="cmd">/ecc:orch-add-feature</span><span class="txt">full feature, end-to-end</span></div>
      <div class="card" style="--c:var(--blue)"><span class="cmd">/ecc:react-test</span><span class="txt">TDD: tests first → component</span></div>
      <div class="card" style="--c:var(--amber)"><span class="cmd">/ecc:react-build</span><span class="txt">fix Vite/Next build errors</span></div>
      <div class="card" style="--c:var(--violet)"><span class="cmd">/ecc:code-review</span><span class="txt">review local diff or PR</span></div>
      <div class="card" style="--c:var(--violet)"><span class="cmd">/ecc:security-scan</span><span class="txt">AgentShield: secrets, hooks, MCP</span></div>
      <div class="card" style="--c:var(--green)"><span class="cmd">/ecc:orch-fix-defect</span><span class="txt">bug → failing test → green</span></div>
      <div class="card" style="--c:var(--green)"><span class="cmd">/ecc:refactor-clean</span><span class="txt">kill dead code, verified</span></div>
      <div class="card" style="--c:var(--amber)"><span class="cmd">/ecc:save-session · resume-session</span><span class="txt">stop today, continue tomorrow</span></div>
      <div class="card" style="--c:var(--amber)"><span class="cmd">/ecc:instinct-status</span><span class="txt">what ECC learned (confidence)</span></div>
      <div class="card" style="--c:var(--cyan)"><span class="cmd">/ecc:cost-report · model-route</span><span class="txt">spend + which model to use</span></div>
      <div class="card" style="--c:var(--blue)"><span class="cmd">/ecc:pr · /ecc:prp-commit</span><span class="txt">PR from branch · NL commit</span></div>
      <div class="card" style="--c:var(--magenta)"><span class="cmd">design skills</span><span class="txt">ui-ux-pro-max · impeccable — AUTO</span></div>
      <div class="card" style="--c:var(--docs,var(--blue))"><span class="cmd">document-skills</span><span class="txt">docx · xlsx · pptx · pdf</span></div>
    </div>

    <div class="foot">
      <span><b class="k">/ecc:</b> = type it</span>
      <span><b class="k">◆ skill</b> = say the name / auto</span>
      <span><b class="k">🤖 hook</b> = happens by itself</span>
      <span>big job → <b>orch-*</b> · unsure → <b>/ecc:plan</b></span>
    </div>
  </main>
</div>

<script>
  (function(){
    var cv = document.getElementById('lunapix');
    if(!cv || !cv.getContext) return;
    var ctx = cv.getContext('2d');
    var letters = 'LUNACORE'.split('');
    var base = 15, pad = 3, scale = 6;
    var cellW = base, cellH = base + 4;
    // offscreen: draw letters stacked vertically
    var off = document.createElement('canvas');
    var octx = off.getContext('2d');
    off.width = cellW + pad*2;
    off.height = letters.length * cellH + pad*2;
    octx.font = '700 ' + base + 'px "Courier New",monospace';
    octx.textAlign = 'center';
    octx.textBaseline = 'top';
    octx.fillStyle = '#ffffff';
    for(var i=0;i<letters.length;i++){
      octx.fillText(letters[i], off.width/2, pad + i*cellH);
    }
    // upscale, no smoothing → chunky pixels
    cv.width = off.width * scale;
    cv.height = off.height * scale;
    var style_w = Math.round(off.width * scale / 2);
    cv.style.width = style_w + 'px';
    cv.style.height = Math.round(off.height * scale / 2) + 'px';
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(off, 0,0, off.width, off.height, 0,0, cv.width, cv.height);
    // tint with cyan→magenta gradient over the pixels
    ctx.globalCompositeOperation = 'source-in';
    var g = ctx.createLinearGradient(0,0,0,cv.height);
    g.addColorStop(0,'#22d3ee');
    g.addColorStop(1,'#f472b6');
    ctx.fillStyle = g;
    ctx.fillRect(0,0,cv.width,cv.height);
    ctx.globalCompositeOperation = 'source-over';
  })();
</script>

