<title>LunaCore // dash</title>
<style>
  :root{
    --bg:#06080f; --panel:#0c1120; --panel-2:#0f1526; --line:#1c2540;
    --ink:#e8ecf7; --muted:#7c88a8;
    --cyan:#22d3ee; --magenta:#f472b6; --blue:#60a5fa;
    --green:#4ade80; --yellow:#fbbf24; --red:#f87171; --violet:#c084fc;
    --amber:#fcd34d;
  }
  *{box-sizing:border-box}
  body{
    margin:0;background:
      radial-gradient(900px 500px at 80% -10%, rgba(34,211,238,.10), transparent 60%),
      radial-gradient(700px 500px at -10% 110%, rgba(244,114,182,.10), transparent 55%),
      var(--bg);
    color:var(--ink);
    font-family:ui-monospace,"Cascadia Code","SF Mono",Consolas,Menlo,monospace;
    min-height:100vh;
  }
  .shell{max-width:1000px;margin:0 auto;padding:clamp(18px,4vw,40px);
    display:grid;grid-template-columns:auto 1fr;gap:clamp(16px,3vw,34px);align-items:start}

  /* pixel rail */
  .rail{display:flex;flex-direction:column;align-items:center;gap:14px;position:sticky;top:24px}
  #lunapix{image-rendering:pixelated;filter:drop-shadow(0 0 14px rgba(34,211,238,.55)) drop-shadow(0 0 26px rgba(244,114,182,.35))}
  .rail .tag{writing-mode:vertical-rl;transform:rotate(180deg);font-size:10px;letter-spacing:.35em;
    text-transform:uppercase;color:var(--muted)}
  .rail .ver{font-size:10px;color:var(--cyan);letter-spacing:.2em;opacity:.8}

  .main{min-width:0}
  .hdr{display:flex;align-items:center;gap:10px;margin:0 0 4px}
  .hdr h1{font-size:16px;margin:0;letter-spacing:.02em;font-weight:700}
  .hdr .cur{width:9px;height:16px;background:var(--cyan);display:inline-block;box-shadow:0 0 10px var(--cyan);animation:blink 1.1s steps(1) infinite}
  @keyframes blink{50%{opacity:0}}
  @media (prefers-reduced-motion:reduce){.hdr .cur{animation:none}}
  .sub{color:var(--muted);font-size:12px;margin:0 0 22px}

  .block-label{font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:var(--muted);
    margin:0 0 10px;display:flex;align-items:center;gap:8px}
  .block-label::after{content:"";flex:1;height:1px;background:linear-gradient(90deg,var(--line),transparent)}

  /* ctx key */
  .ctx{display:flex;flex-direction:column;gap:8px;margin-bottom:26px}
  .ctx .row{display:flex;align-items:center;gap:12px;background:var(--panel);border:1px solid var(--line);
    border-radius:10px;padding:10px 14px}
  .ctx .led{width:12px;height:12px;border-radius:50%;flex:none}
  .ctx .pct{font-weight:700;font-size:13px;min-width:74px}
  .ctx .say{font-size:13px;color:var(--ink)}
  .ctx .say b{color:var(--muted);font-weight:400}
  .g .led{background:var(--green);box-shadow:0 0 10px var(--green)} .g .pct{color:var(--green)}
  .y .led{background:var(--yellow);box-shadow:0 0 10px var(--yellow)} .y .pct{color:var(--yellow)}
  .r .led{background:var(--red);box-shadow:0 0 10px var(--red)} .r .pct{color:var(--red)}

  /* commands */
  .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px}
  .card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:11px 13px;
    transition:border-color .15s ease, transform .15s ease}
  .card:hover{border-color:color-mix(in oklab,var(--c,var(--cyan)),transparent 40%);transform:translateY(-1px)}
  .card .cmd{font-size:12.5px;font-weight:700;color:var(--c,var(--cyan));display:block;margin-bottom:3px;
    overflow-x:auto;white-space:nowrap}
  .card .cmd::-webkit-scrollbar{height:0}
  .card .txt{font-size:12px;color:var(--muted);line-height:1.4}

  .foot{margin-top:24px;font-size:11.5px;color:var(--muted);display:flex;flex-wrap:wrap;gap:6px 16px}
  .foot span b{color:var(--cyan)}
  .k{color:var(--magenta)}

  @media (max-width:600px){
    .shell{grid-template-columns:1fr}
    .rail{flex-direction:row;position:static;justify-content:flex-start}
    .rail .tag{writing-mode:horizontal-tb;transform:none}
  }
</style>

